```cpp
static bool onButtonClick_Button1(ZKButton *pButton) {
    static int rot = 0;
    CONFIGMANAGER->setScreenRotate(rot);   // 先转屏幕
    CONFIGMANAGER->setTouchRotate(rot);    // 再转触摸
    mActivityPtr->relayout(((rot == 0) || (rot == 180)) ? "main.ftu" : "main_p.ftu");
