## 3. 持续取流保活（关键）

```cpp
class UvcCameraDetection: public mpi::Task<> {
  virtual void doTask() override {
    while (isStarted()) {
      try {
        mpi::SharedVideoDevice device(mpi::VIDEO_DEVICE_REAR);  // 占用后路设备
        while (isStarted()) { wait(); }                          // mpi 持续拉流
      } catch (mpi::Exception& e) { Thread::sleep(100); }
    }
  }
};
